import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { Status, Summary } from '../types'

const MODEL = 'haiku'
const ACCENT = 'warning'
const SCROLL_SETTLE_MS = 400

type Sections = { know: boolean; next: boolean }

const KNOW_HEADER = 'You Should Know'
const NEXT_HEADER = 'What To Do Next'

const systemFor = (sections: Sections) => {
  const blocks = [`TLDR;\n<2-3 short sentences: ${sections.next ? 'the conclusion' : 'the conclusion and what to do'}>`]
  if (sections.know) {
    blocks.push(`${KNOW_HEADER}\n- <important fact, warning, decision, file path, command, or caveat>\n- <...>`)
  }
  if (sections.next) {
    blocks.push(`${NEXT_HEADER}\n- <concrete next step for the reader: command to run, file to check, decision to make>\n- <...>`)
  }
  const bulletRule = sections.know || sections.next ? '1-6 bullets per section, each one line. If nothing to do next, write "- Nothing." ' : ''
  return `You summarize an AI assistant's response for a reader who finds long responses hard to read.
Output exactly this format, plain text, nothing before or after:

${blocks.join('\n\n')}

Rules: ${bulletRule}Keep exact names, paths, commands, numbers. No emoji. No markdown. No filler. Do not invent anything not in the response.`
}

let sections: Sections = { know: true, next: true }

const view = atom({ plugin: 'tldr', key: 'view' } as const, null)
const isCollapsed = atom({ plugin: 'tldr', key: 'isCollapsed' } as const, false)
const status = atom({ plugin: 'tldr', key: 'status' } as const, null)

const setStatus = ($: EngineInterface, next: Status | null) => update($, status, () => next)

export const parse = (text: string, want: Sections): Summary => {
  const summary: Summary = { tldr: [], know: [], next: [] }
  const seen = new Set<keyof Summary>(['tldr'])
  let section: keyof Summary = 'tldr'
  for (const line of text.split('\n').map(l => l.trim()).filter(Boolean)) {
    if (/^tldr;?$/i.test(line)) continue
    if (/^you should know/i.test(line)) {
      section = 'know'
    } else if (/^what to do next/i.test(line)) {
      section = 'next'
    } else {
      summary[section].push(section === 'tldr' ? line : line.replace(/^[-*]\s*/, ''))
      continue
    }
    seen.add(section)
  }
  if (want.know && !seen.has('know')) {
    throw new Error(`tldr: summary missing "${KNOW_HEADER}" section`)
  }
  if (want.next && !seen.has('next')) {
    throw new Error(`tldr: summary missing "${NEXT_HEADER}" section`)
  }
  return summary
}

const hashOf = async (text: string) => {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, '0')).join('')
}

const storeKey = async ($: EngineInterface) => `summaries:${await $.session.id()}`

const loadAll = async ($: EngineInterface) =>
  ((await $.store.get(await storeKey($))) ?? {}) as Record<string, Summary>

const pending = new Set<string>()
let latestText: string | null = null
let focusId: string | null = null
let settle: Timer | null = null

const summaryFor = async ($: EngineInterface, text: string, what: string): Promise<Summary | null> => {
  const hash = await hashOf(`${sections.know ? 'k' : ''}${sections.next ? 'n' : ''}:${text}`)
  const hit = (await loadAll($))[hash]
  if (hit) return hit
  if (pending.has(hash)) return null

  pending.add(hash)
  await setStatus($, { text: `summarizing ${what} (${MODEL})...`, isError: false })
  try {
    const reply = await $.model.complete({
      model: MODEL,
      system: systemFor(sections),
      prompt: `<response>\n${text}\n</response>`,
      maxTokens: 600,
    })
    if (!reply.isAnswered) {
      const detail = reply.reason === 'api-error' ? `api-error ${reply.status} ${reply.error}` : reply.reason
      await setStatus($, { text: `failed: ${detail}`, isError: true })
      return null
    }
    let parsed: Summary
    try {
      parsed = parse(reply.text, sections)
    } catch (err) {
      await setStatus($, { text: 'failed: summary not in expected section format', isError: true })
      throw err
    }
    const all = await loadAll($)
    await $.store.set(await storeKey($), { ...all, [hash]: parsed })
    await setStatus($, null)
    return parsed
  } finally {
    pending.delete(hash)
  }
}

const showLatest = async ($: EngineInterface) => {
  if (latestText === null) {
    await update($, view, () => null)
    return
  }
  const summary = await summaryFor($, latestText, 'latest response')
  if (summary && focusId === null) {
    await update($, view, () => ({ summary, isLatest: true }))
  }
}

const showFocused = async ($: EngineInterface, id: string, text: string) => {
  const summary = await summaryFor($, text, 'message at bottom of view')
  if (summary && focusId === id) {
    await update($, view, () => ({ summary, isLatest: false }))
  }
}

export const register: Register = (on, options) => {
  const MIN_CHARS = options.minChars
  if (typeof MIN_CHARS !== 'number' || !Number.isInteger(MIN_CHARS) || MIN_CHARS < 1) {
    throw new Error(`tldr: minChars must be a positive integer, got ${String(MIN_CHARS)}`)
  }
  const { showKnow, showNext } = options
  if (typeof showKnow !== 'boolean' || typeof showNext !== 'boolean') {
    throw new Error(`tldr: showKnow and showNext must be booleans, got ${String(showKnow)}, ${String(showNext)}`)
  }
  sections = { know: showKnow, next: showNext }

  on('prompt.submit', async ($, e, next) => {
    latestText = null
    focusId = null
    await update($, view, () => null)
    await setStatus($, { text: 'waiting for response to finish', isError: false })
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId) {
      return result
    }
    if (e.reason !== 'answer') {
      await setStatus($, { text: `skipped: turn ended by ${e.reason}`, isError: false })
      return result
    }
    if (e.answer.length < MIN_CHARS) {
      await setStatus($, { text: `skipped: reply ${e.answer.length} chars, under ${MIN_CHARS}`, isError: false })
      return result
    }
    latestText = e.answer
    focusId = null
    await showLatest($)
    return result
  })

  on('classic.SessionStart', { source: 'resume' }, async ($, e, next) => {
    const result = await next(e)
    focusId = null
    const last = (await $.session.messages()).findLast(m => m.role === 'assistant' && m.text)
    latestText = last && last.text.length >= MIN_CHARS ? last.text : null
    if (latestText === null) {
      await setStatus($, { text: `skipped: last reply of resumed session under ${MIN_CHARS} chars`, isError: false })
    }
    await showLatest($)
    return result
  })

  on('ui.render', { component: 'AssistantMessage' }, ($, e, next) => {
    const pos = e.props.onScreen
    if (pos === null && focusId === e.requestId) {
      focusId = null
      settle?.cancel()
      void showLatest($)
    }
    const isCutAtBottom = pos && pos.last < pos.of - 1
    if (!isCutAtBottom || focusId === e.requestId || e.props.text.length < MIN_CHARS) {
      return next(e)
    }

    const id = e.requestId
    const text = e.props.text
    focusId = id
    settle?.cancel()
    settle = $.clock.after(SCROLL_SETTLE_MS, () => void showFocused($, id, text))
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const v = await read($, view)
    const s = await read($, status)
    if ((v === null && s === null) || e.props.hasSurvey) {
      return next(e)
    }

    const { Box, Button, Text } = $.ui.resolve(e)
    const statusLine = s && (
      <Text color={s.isError ? 'error' : undefined} dimColor={!s.isError} wrap="truncate-end">
        {`  ${s.text}`}
      </Text>
    )

    if (v === null) {
      return (
        <Box width={e.props.bodyColumns}>
          <Box flexShrink={0}>
            <Text color={ACCENT} bold>
              {'>> TLDR;'}
            </Text>
          </Box>
          <Box flexShrink={1} minWidth={0}>
            {statusLine}
          </Box>
        </Box>
      )
    }

    const { summary } = v
    const collapsed = await read($, isCollapsed)
    const toggle = (
      <Box flexShrink={0}>
        <Button
          key="toggle"
          label={collapsed ? '+' : '-'}
          hotkey="t"
          onPress={() => update($, isCollapsed, c => !c)}
        />
      </Box>
    )
    const label = (
      <Box flexShrink={0}>
        <Text backgroundColor={ACCENT} color="inverseText" bold wrap="truncate-end">
          {' >> TLDR; '}
        </Text>
      </Box>
    )

    const bullets = (prefix: string, header: string, items: string[]) => (
      <Box key={prefix} flexDirection="column">
        <Text> </Text>
        <Text color={ACCENT} bold>
          {header}
        </Text>
        {items.map((item, i) => (
          <Text key={`${prefix}${i}`}>
            <Text color={ACCENT}>{' > '}</Text>
            {item}
          </Text>
        ))}
      </Box>
    )

    if (collapsed) {
      return (
        <Box borderStyle="double" borderColor={ACCENT} paddingX={1} width={e.props.bodyColumns}>
          {label}
          <Box flexGrow={1} flexShrink={1} minWidth={0} paddingX={1}>
            <Text bold wrap="truncate-end">
              {summary.tldr.join(' ')}
            </Text>
          </Box>
          {toggle}
        </Box>
      )
    }

    return (
      <Box
        flexDirection="column"
        borderStyle="double"
        borderColor={ACCENT}
        paddingX={1}
        width={e.props.bodyColumns}
      >
        <Box>
          {label}
          <Box flexGrow={1}>
            {statusLine ?? <Text dimColor>{v.isLatest ? '  latest response' : '  message at bottom of view'}</Text>}
          </Box>
          {toggle}
        </Box>
        <Text bold>{summary.tldr.join(' ')}</Text>
        {sections.know && bullets('k', `!! ${KNOW_HEADER}`, summary.know)}
        {sections.next && bullets('n', `>> ${NEXT_HEADER}`, summary.next)}
      </Box>
    )
  })
}

