{
  "name": "tldr",
  "version": "0.4.0",
  "description": "Shows a TLDR, You Should Know and What To Do Next box above the prompt after long responses",
  "types": "./types/index.d.ts",
  "userConfig": {
    "minChars": {
      "type": "number",
      "title": "tldr: Minimum reply length",
      "description": "Summarize only replies with at least this many characters",
      "default": 800,
      "min": 1
    },
    "showKnow": {
      "type": "boolean",
      "title": "tldr: Show You Should Know",
      "description": "Include the You Should Know section in the summary",
      "default": true
    },
    "showNext": {
      "type": "boolean",
      "title": "tldr: Show What To Do Next",
      "description": "Include the What To Do Next section in the summary",
      "default": true
    }
  }
}

