export type Summary = { tldr: string[]; know: string[]; next: string[] }
export type View = { summary: Summary; isLatest: boolean }
export type Status = { text: string; isError: boolean }

declare module 'claude-code' {
  interface PluginState {
    tldr: { view: View | null; isCollapsed: boolean; status: Status | null }
  }
}
